#include <stdio.h>
#define MAXN 8
int parent[MAXN];
int find(int x){ int r=x; while(parent[r]!=r) r=parent[r];
    while(parent[x]!=r){ int t=parent[x]; parent[x]=r; x=t; } return r; }
int main(void){
    int n=5;
    for(int i=0;i<n;i++) parent[i]=i;
    /* 构造退化链 0<-1<-2<-3<-4（不优化时 find 要爬 4 层） */
    parent[1]=0; parent[2]=1; parent[3]=2; parent[4]=3;
    printf("压缩前 parent = ");
    for(int i=0;i<n;i++) printf("%d ", parent[i]);
    printf("\n");
    printf("调用 find(4) 返回根 = %d\n", find(4));
    printf("压缩后 parent = ");
    for(int i=0;i<n;i++) printf("%d ", parent[i]);
    printf("\n");
    return 0;
}
